'use strict';

// MAIN //

/**
* Tests whether a document contains an error diagnostic.
*
* @private
* @param {Object} doc - semantic document
* @returns {boolean} boolean
*/
function hasErrors( doc ) {
	var i;
	for ( i = 0; i < doc.diagnostics.length; i++ ) {
		if ( doc.diagnostics[ i ].severity === 'error' ) {
			return true;
		}
	}
	return false;
}


// EXPORTS //

module.exports = hasErrors;
